return [{
  json: {
    wpBaseUrl: $env.WP_BASE_URL || 'http://localhost:10020',
    wpAuth: 'Basic ' + Buffer.from(($env.WP_USERNAME || '') + ':' + ($env.WP_APP_PASSWORD || '')).toString('base64'),
    anthropicKey: $env.ANTHROPIC_API_KEY || '',
    slackToken: $env.SLACK_BOT_TOKEN || '',
    slackChannel: $env.SLACK_DEFAULT_CHANNEL || '',
  }
}];

function stripHtml(html) {
  if (!html) return '';
  return html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

function extractHeadings(html) {
  if (!html) return [];
  return [...html.matchAll(/<h([2-6])[^>]*>(.*?)<\/h\1>/gi)]
    .map(m => ({ level: parseInt(m[1]), text: stripHtml(m[2]) }));
}

function countWords(text) {
  if (!text) return 0;
  return text.trim().split(/\s+/).filter(w => w.length > 0).length;
}

function extractLinks(html) {
  if (!html) return [];
  return [...html.matchAll(/<a[^>]+href=["']([^"']+)["'][^>]*>/gi)]
    .map(m => m[1]);
}

function extractImages(html) {
  if (!html) return [];
  return [...html.matchAll(/<img[^>]+>/gi)].map(m => {
    const altM = m[0].match(/alt=["']([^"']*)["']/i);
    return { hasAlt: !!(altM && altM[1]), alt: altM?.[1] || '' };
  });
}

function extractBoldClaims(html) {
  if (!html) return [];
  return [...html.matchAll(/<strong[^>]*>(.*?)<\/strong>/gi)]
    .map(m => stripHtml(m[1]).trim()).filter(Boolean);
}

function extractStats(text) {
  if (!text) return [];
  const regex = /\b\d+(?:\.\d+)?%|\$\s*\d+(?:\.\d+)?(?:\s*[kKmMbB])?|\b\d+(?:\.\d+)?\s*(?:times|x|percent)\b/g;
  return [...new Set(text.match(regex) || [])];
}

function extractQuestionHeadings(headings) {
  const qWords = /^(what|why|how|when|where|who|which|can|does|is|are|do|should|will)/i;
  return headings.filter(h => qWords.test(h.text) || h.text.endsWith('?'));
}

const allItems = $input.all();
const posts = (allItems.length === 1 && Array.isArray(allItems[0].json))
  ? allItems[0].json
  : allItems.map(item => item.json);

const wpBase = $('Load Config').first().json.wpBaseUrl;

const summaries = posts.map(post => {
  const content = post.content?.rendered || '';
  const plainText = stripHtml(content);
  const headings = extractHeadings(content);
  const images = extractImages(content);
  const yoast = post.yoast_head_json || {};
  const acf = post.acf || {};
  return {
    id: post.id,
    status: post.status,
    title: (post.title?.rendered || '').trim(),
    slug: post.slug,
    wordCount: countWords(plainText),
    headings,
    questionHeadings: extractQuestionHeadings(headings),
    linkCount: extractLinks(content).length,
    imageCount: images.length,
    imagesWithAlt: images.filter(i => i.hasAlt).length,
    boldClaims: extractBoldClaims(content),
    stats: extractStats(plainText),
    openingWords: plainText.split(/\s+/).slice(0, 150).join(' '),
    seo: {
      seoTitle: yoast.title || '',
      metaDescription: yoast.description || '',
      ogImage: yoast.og_image?.[0]?.url || '',
      canonical: yoast.canonical || '',
      readingTime: yoast.twitter_misc?.['Est. reading time'] || '',
    },
    acf: {
      blog_lead: acf.blog_lead || null,
      resource_card_title: acf.resource_card_title || null,
      resource_card_image: acf.resource_card_image || null,
      resource_excerpt: acf.resource_excerpt || null,
      resource_cta_text: acf.resource_cta_text || null,
    },
    editLink: wpBase + '/wp-admin/post.php?post=' + post.id + '&action=edit',
    postLink: post.link || '',
  };
});

const summaryJson = JSON.stringify(summaries, null, 2);

const seoPrompt = 'You are an expert SEO analyst for B2B SaaS content. Analyze the following WordPress blog post data and provide actionable SEO recommendations.\n\nBLOG POST DATA:\n' + summaryJson + '\n\nAnalyze each post across these 7 dimensions:\n1. Title & Slug -- SEO title compelling and keyword-rich? Under 60 chars? Slug match intent?\n2. Meta Description -- Present? ~155 chars? Clear value prop and CTA?\n3. Content Structure -- H2/H3 hierarchy logical? Word count 1200+? Scannable?\n4. Internal Linking -- Links to /skills/, /resources/, /demo/, or other blog posts?\n5. Images -- Present? All have descriptive alt text?\n6. ACF Fields -- blog_lead set? resource_card_title and resource_excerpt populated? resource_card_image set (non-null)?\n7. Score & Fixes -- Overall score 1-10. Top 3 priority fixes only.\n\nFormat as a clear markdown report. Be specific and actionable. Start each post section with its title as a heading.';

const aeoPrompt = 'You are an expert in Answer Engine Optimization (AEO) and Generative Engine Optimization (GEO) -- how well content is cited by AI systems like ChatGPT, Perplexity, Google AI Overviews, and Claude.\n\nBLOG POST DATA:\n' + summaryJson + '\n\nAnalyze each post across these 7 dimensions:\n1. Citability -- Quotable, specific claims with concrete numbers? Facts AI can cite confidently?\n2. Entity Clarity -- Is the brand clearly named? Products mentioned by name? Target audience consistent?\n3. Question Targeting -- List 3-5 questions this content should answer. Does it answer them directly?\n4. Structured Data -- Schema markup? Lists, tables, bold key terms? Definition patterns?\n5. Source Authority -- First-party data, case study results, or original research? Or mostly vague claims?\n6. Content Gaps -- Missing: FAQ section? Comparisons? Key term definitions? TL;DR summary?\n7. Score & Fixes -- Score 1-10 for AEO/GEO readiness. Top 3 priority improvements only.\n\nFormat as a clear markdown report. Be specific. Start each post section with its title as a heading.';

return [{
  json: {
    summaries,
    postCount: summaries.length,
    seoRequestBody: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 4096,
      messages: [{ role: 'user', content: seoPrompt }]
    },
    aeoRequestBody: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 4096,
      messages: [{ role: 'user', content: aeoPrompt }]
    }
  }
}];

function truncateForSlack(text, maxLen) {
  maxLen = maxLen || 2900;
  if (!text) return '_No report generated_';
  let slack = text
    .replace(/^#{1,3}\s+(.+)$/gm, '*$1*')
    .replace(/\*\*(.+?)\*\*/g, '*$1*');
  if (slack.length > maxLen) {
    slack = slack.substring(0, maxLen) + '\n\n_[truncated]_';
  }
  return slack;
}

const summaries = $('Build Summaries').first().json.summaries;
const postCount = $('Build Summaries').first().json.postCount;
const seoText = $('SEO Audit (Claude)').first().json.content?.[0]?.text || 'SEO audit unavailable';
const aeoText = $('AEO Audit (Claude)').first().json.content?.[0]?.text || 'AEO audit unavailable';
const slackChannel = $('Load Config').first().json.slackChannel;
const slackToken = $('Load Config').first().json.slackToken;

const postList = summaries.map(p =>
  '\u2022 *' + p.title + '* (' + p.wordCount + ' words) \u2014 <' + p.editLink + '|Edit in WP>'
).join('\n');

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: 'Content Audit: ' + postCount + ' Blog Post' + (postCount !== 1 ? 's' : ''), emoji: true }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: postList }
  },
  { type: 'divider' },
  {
    type: 'header',
    text: { type: 'plain_text', text: 'SEO Audit', emoji: true }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: truncateForSlack(seoText) }
  },
  { type: 'divider' },
  {
    type: 'header',
    text: { type: 'plain_text', text: 'AEO/GEO Audit', emoji: true }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: truncateForSlack(aeoText) }
  }
];

return [{
  json: {
    slackToken,
    channel: slackChannel,
    text: 'Content Audit: ' + postCount + ' blog post' + (postCount !== 1 ? 's' : '') + ' analyzed',
    blocks
  }
}];
